# Internal publication-figure input checks and shared drawing utilities.
# No external model labels, calibration accuracy, or inferential claims are
# generated by these purely descriptive plotting helpers.

.aqt_pub_data <- function(x, columns, context) {
  if (!is.data.frame(x) || anyDuplicated(names(x)) ||
      !all(columns %in% names(x)) || !nrow(x)) {
    stop(context, ": nonempty data.frame with columns ",
         paste(columns,collapse=", "), " required",call.=FALSE)
  }
  x
}

.aqt_pub_number <- function(x, name, finite=TRUE, positive=FALSE) {
  if (!is.numeric(x) || length(x)!=1L || is.na(x) ||
      (finite && !is.finite(x)) || (positive && x<=0))
    stop(name," must be a ",if(positive) "positive " else "",
         if(finite) "finite " else "","numeric scalar",call.=FALSE)
  invisible(x)
}

.aqt_pub_column_numeric <- function(x, name, finite=TRUE) {
  if (!is.numeric(x[[name]]) ||
      (finite && any(!is.finite(x[[name]]))))
    stop(name," must contain finite numeric values",call.=FALSE)
  invisible(TRUE)
}

.aqt_pub_id <- function(x,name) {
  if (!is.character(x) || length(x)!=1L || is.na(x) ||
      !nzchar(trimws(x)))
    stop(name," must be a nonempty character scalar",call.=FALSE)
  invisible(x)
}

.aqt_pub_panels <- function(n) {
  c(if(n<=2L) 1L else ceiling(n/2),if(n==1L) 1L else 2L)
}

.aqt_pub_scope <- function(x,name) {
  v <- as.character(x[[name]])
  if (anyNA(v) || any(!nzchar(trimws(v))))
    stop("Missing or blank ",name," labels",call.=FALSE)
  v
}

.aqt_pub_physical_xyz <- function(x,columns) {
  for (name in columns) .aqt_pub_column_numeric(x,name)
  invisible(TRUE)
}

.aqt_pub_project_xyz <- function(xyz,bounds) {
  if (!is.matrix(xyz) || ncol(xyz)!=3L || any(!is.finite(xyz)))
    stop("Expected finite three-column XYZ matrix",call.=FALSE)
  if (!is.matrix(bounds) || !identical(dim(bounds),c(2L,3L)) ||
      any(!is.finite(bounds)) || any(bounds[2L,]<=bounds[1L,]))
    stop("Invalid XYZ bounds",call.=FALSE)
  len <- max(bounds[2L,]-bounds[1L,])
  z <- sweep(xyz,2L,bounds[1L,],"-")/len
  cbind(x=z[,1L]-.6*z[,2L],
        y=.24*z[,1L]+.48*z[,2L]+1.04*z[,3L])
}

.aqt_pub_draw_circular_grid <- function(rmax) {
  theta <- seq(0,2*pi,length.out=201L)
  for (fraction in c(.25,.5,.75,1)) {
    graphics::lines(fraction*rmax*cos(theta),
                    fraction*rmax*sin(theta),col="#DAE1E5",lwd=.7)
  }
  for (angle in seq(0,2*pi,length.out=9L)[-9L])
    graphics::segments(0,0,rmax*cos(angle),rmax*sin(angle),
                       col="#DAE1E5",lwd=.7)
  invisible(NULL)
}

.aqt_pub_circular_summary <- function(angles,weights) {
  theta <- atan2(sum(weights*sin(angles)),sum(weights*cos(angles)))
  concentration <- sqrt(sum(weights*cos(angles))^2+
                        sum(weights*sin(angles))^2)/sum(weights)
  list(mean_heading_rad=theta,
       circular_resultant_length=concentration)
}
